function ArchiveForm({
  fields,
  initial,
  current,
  submitLabel,
  pending,
  error,
  onSubmit,
  onCancel
}: {
  fields: readonly ArchiveField[];
  initial: ArchiveValues;
  current?: Detail | null;
  submitLabel: string;
  pending: boolean;
  error: { message: string } | null;
  onSubmit: (values: ArchiveValues) => void;
  onCancel?: () => void;
}) {
  const [values, setValues] = useState<ArchiveValues>(initial);
  const [problem, setProblem] = useState<string | null>(null);
  const set: ArchiveSetter = (key, value) => setValues(current => ({ ...current, [key]: value }));
  const submit = (event: FormEvent) => {
    event.preventDefault();
    setProblem(null);
    try {
      onSubmit(values);
    } catch (err) {
      setProblem(err instanceof Error ? err.message : String(err));
    }
  };
  return (
    <form onSubmit={submit} className="grid max-w-xl gap-4">
      {fields.map(field => (
        <Fragment key={field}>{renderArchiveField(field, values, set, current)}</Fragment>
      ))}
      <ErrorNote error={error ?? (problem ? { message: problem } : null)} />
      <div className="flex gap-2">
        <Button type="submit" disabled={pending}>
          {submitLabel}
        </Button>
        {onCancel ? (
          <Button type="button" variant="ghost" onClick={onCancel}>
            Cancel
          </Button>
        ) : null}
      </div>
    </form>
  );
}

function ArchiveLayoutInner() {
  return <div className="h-full min-h-0 overflow-hidden"><Outlet /></div>;
}

function ArchiveIndexInner() {
  const [page, setPage] = useState(1);
  const [archived, setArchived] = useState(false);
  const [sort, setSort] = useState<string | undefined>(undefined);
  const [search, setSearch] = useState("");
  const q = useDebounced(search);
  const [filters, setFilters] = useState<{ published?: string; author_id?: string; status?: string }>({});
  const [openAction, setOpenAction] = useState<string | null>(null);
  void openAction;
  void setOpenAction;
  const setFilter = (key: keyof typeof filters, value: string) => {
    setFilters(current => ({ ...current, [key]: value }));
    setPage(1);
  };
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const input = {
    page,
    page_size: PAGE_SIZE,
    sort,
    q: q || undefined,
    published: filters.published === "true" ? true : filters.published === "false" ? false : undefined, author_id: filters.author_id || undefined, status: filters.status || undefined,
    ...(archived ? { archived: true } : {})
  } as Inputs["posts"]["list"];
  const list = useQuery({ queryKey: [...KEY, "list", input], queryFn: () => client.posts.list(input) });
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const unpublish_allAction = useMutation({
    mutationFn: (input: Inputs["posts"]["unpublish_all"]) => client.posts.unpublish_all(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  return (
    <div className="flex h-full min-h-0 flex-col">
      <PaneHeader title="Archive" count={list.data?.page.total}>
          <Button
            variant={archived ? "secondary" : "ghost"}
            size="sm"
            aria-pressed={archived}
            onClick={() => {
              setArchived(current => !current);
              setPage(1);
            }}
          >
            {archived ? "Showing archived" : "Show archived"}
          </Button>
          {canCreate(user) ? (
            <Link to="/archive/new" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="New article">
              <Plus />
            </Link>
          ) : null}
          {canUnpublishAll(user) ? (
            <Button variant="outline" size="sm" disabled={unpublish_allAction.isPending} onClick={() => unpublish_allAction.mutate({})}>
              Unpublish All
            </Button>
          ) : null}
      </PaneHeader>

        <ErrorNote error={unpublish_allAction.error} className="m-4" />
      <div className="flex flex-wrap items-center gap-2 border-b border-border px-4 py-2">
          <Input type="search" placeholder="Search" className="w-56" value={search} onChange={e => { setSearch(e.target.value); setPage(1); }} />
          <select aria-label="Published" className={selectClass + " w-auto"} value={filters.published ?? ""} onChange={e => setFilter("published", e.target.value)}>
            <option value="">Published: any</option>
            <option value="true">Published: yes</option>
            <option value="false">Published: no</option>
          </select>
          <Input aria-label="Author" type="text" placeholder="Author" className="w-40" value={filters.author_id ?? ""} onChange={e => setFilter("author_id", e.target.value)} />
          <select aria-label="Status" className={selectClass + " w-auto"} value={filters.status ?? ""} onChange={e => setFilter("status", e.target.value)}>
            <option value="">Status: any</option>
            <option value="draft">draft</option>
            <option value="in_review">in_review</option>
            <option value="approved">approved</option>
            <option value="retired">retired</option>
          </select>
      </div>
      <div className="min-h-0 flex-1 overflow-auto px-4">
        {list.isPending ? (
          <ListSkeleton />
        ) : list.error ? (
          <ErrorNote error={list.error} className="m-4" />
        ) : list.data.data.length === 0 ? (
          <EmptyPane>No archive found.</EmptyPane>
        ) : (
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead>
                  <SortHeader field="title" sort={sort} onSort={next => { setSort(next); setPage(1); }}>
                    Title
                  </SortHeader>
                </TableHead>
                <TableHead>Published</TableHead>
                <TableHead>
                  <SortHeader field="posted_at" sort={sort} onSort={next => { setSort(next); setPage(1); }}>
                    Posted At
                  </SortHeader>
                </TableHead>
                <TableHead>Author</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {list.data.data.map((row: Row) => (
                <TableRow key={text(row.id)} className={cn("cursor-pointer", row.archived_at && "text-muted-foreground")} onClick={() => navigate({ to: "/archive/$id", params: { id: text(row.id) } })}>
                  <TableCell>{text(row.title)}</TableCell>
                  <TableCell>{(row.published ? "Published" : "Not published")}</TableCell>
                  <TableCell>{formatDateTime(row.posted_at)}</TableCell>
                  <TableCell>{(row.author ? text(row.author.name) : text(row.author_id))}</TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        )}
      </div>
      {list.data ? <Pagination page={page} pageSize={PAGE_SIZE} total={list.data.page.total} onChange={setPage} /> : null}
    </div>
  );
}

function ArchiveNewInner() {
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const createRow = useMutation({
    mutationFn: (input: Input<"create">) => client.posts.create(input),
    onSuccess: async row => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/archive/$id", params: { id: text(row.id) } });
    }
  });
  return (
    <Pane title="New article" actions={<Link to="/archive" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>}>
      <ArchiveForm
        fields={ARCHIVE_CREATE}
        initial={EMPTY_ARCHIVE}
        submitLabel="Create"
        pending={createRow.isPending}
        error={createRow.error}
        onSubmit={values => createRow.mutate(toArchiveCreateInput(values))}
      />
    </Pane>
  );
}

function ArchiveDetailInner() {
  const { id: rawId } = useParams({ from: "/archive/$id" });
  const id = idOf(rawId);
  const navigate = useNavigate();
  const queryClient = useQueryClient();
  const [editing, setEditing] = useState(false);
  const [openAction, setOpenAction] = useState<string | null>(null);
  useEffect(() => {
    setEditing(false);
    setOpenAction(null);
  }, [id]);
  const query = useQuery({ queryKey: [...KEY, "get", id], queryFn: () => client.posts.get({ id }) });
  const session = useQuery({ queryKey: ["auth", "session"], queryFn: () => client.auth.session() });
  const user = sessionUser(session.data);
  void user;
  const updateRow = useMutation({
    mutationFn: (input: Inputs["posts"]["update"]) => client.posts.update(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      setEditing(false);
    }
  });
  const removeRow = useMutation({
    mutationFn: (input: Inputs["posts"]["delete"]) => client.posts.delete(input),
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: KEY });
      await navigate({ to: "/archive" });
    }
  });
  const publishAction = useMutation({
    mutationFn: (input: Inputs["posts"]["publish"]) => client.posts.publish(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const lockAction = useMutation({
    mutationFn: (input: Inputs["posts"]["lock"]) => client.posts.lock(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const unlockAction = useMutation({
    mutationFn: (input: Inputs["posts"]["unlock"]) => client.posts.unlock(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const archiveAction = useMutation({
    mutationFn: (input: Inputs["posts"]["archive"]) => client.posts.archive(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const restoreAction = useMutation({
    mutationFn: (input: Inputs["posts"]["restore"]) => client.posts.restore(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const submitAction = useMutation({
    mutationFn: (input: Inputs["posts"]["submit"]) => client.posts.submit(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const approveAction = useMutation({
    mutationFn: (input: Inputs["posts"]["approve"]) => client.posts.approve(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const rejectAction = useMutation({
    mutationFn: (input: Inputs["posts"]["reject"]) => client.posts.reject(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  const retireAction = useMutation({
    mutationFn: (input: Inputs["posts"]["retire"]) => client.posts.retire(input),
    onSuccess: async () => {
      setOpenAction(null);
      await queryClient.invalidateQueries({ queryKey: KEY });
    }
  });
  if (query.isPending) return <PaneSkeleton />;
  if (query.error) return <ErrorNote error={query.error} className="m-6" />;
  const row: Detail = query.data;
  return (
    <Pane
      title={text(row.title) || "Article " + text(row.id)}
      actions={
        <>
          <Link to="/archive" className={buttonVariants({ variant: "ghost", size: "icon-sm" })} aria-label="Back">
            <ArrowLeft />
          </Link>
          {canPublish(user, row) ? (
            <Button variant="outline" size="sm" disabled={publishAction.isPending} onClick={() => publishAction.mutate({ id })}>
              Publish
            </Button>
          ) : null}
          {canLock(user, row) ? (
            <Button variant="outline" size="sm" disabled={lockAction.isPending} onClick={() => lockAction.mutate({ id })}>
              Lock
            </Button>
          ) : null}
          {canUnlock(user, row) ? (
            <Button variant="outline" size="sm" disabled={unlockAction.isPending} onClick={() => unlockAction.mutate({ id })}>
              Unlock
            </Button>
          ) : null}
          {canArchive(user, row) && !row.archived_at ? (
            <Button variant="outline" size="sm" disabled={archiveAction.isPending} onClick={() => archiveAction.mutate({ id })}>
              Archive
            </Button>
          ) : null}
          {canRestore(user, row) && row.archived_at ? (
            <Button variant="outline" size="sm" disabled={restoreAction.isPending} onClick={() => restoreAction.mutate({ id })}>
              Restore
            </Button>
          ) : null}
          {canSubmit(user, row) && ["draft"].includes(String(row.status)) ? (
            <Button variant="outline" size="sm" disabled={submitAction.isPending} onClick={() => submitAction.mutate({ id })}>
              Submit
            </Button>
          ) : null}
          {canApprove(user, row) && ["in_review"].includes(String(row.status)) ? (
            <Button variant="outline" size="sm" disabled={approveAction.isPending} onClick={() => approveAction.mutate({ id })}>
              Approve
            </Button>
          ) : null}
          {canReject(user, row) && ["in_review"].includes(String(row.status)) ? (
            <Button variant="outline" size="sm" disabled={rejectAction.isPending} onClick={() => rejectAction.mutate({ id })}>
              Reject
            </Button>
          ) : null}
          {canRetire(user, row) && ["approved"].includes(String(row.status)) ? (
            <Button variant="outline" size="sm" disabled={retireAction.isPending} onClick={() => retireAction.mutate({ id })}>
              Retire
            </Button>
          ) : null}
          {canUpdate(user, row) ? (
            <Button variant="outline" size="sm" onClick={() => setEditing(current => !current)}>
              {editing ? "Cancel" : "Edit"}
            </Button>
          ) : null}
          {canDelete(user, row) ? (
            <Button
              variant="destructive"
              size="sm"
              disabled={removeRow.isPending}
              onClick={() => {
                if (window.confirm("Delete this article?")) removeRow.mutate({ id });
              }}
            >
              Delete
            </Button>
          ) : null}
        </>
      }
    >

      <ErrorNote error={publishAction.error} className="mb-4" />
      <ErrorNote error={lockAction.error} className="mb-4" />
      <ErrorNote error={unlockAction.error} className="mb-4" />
      <ErrorNote error={archiveAction.error} className="mb-4" />
      <ErrorNote error={restoreAction.error} className="mb-4" />
      <ErrorNote error={submitAction.error} className="mb-4" />
      <ErrorNote error={approveAction.error} className="mb-4" />
      <ErrorNote error={rejectAction.error} className="mb-4" />
      <ErrorNote error={retireAction.error} className="mb-4" />
      {editing ? (
        <ArchiveForm
          fields={ARCHIVE_UPDATE}
          initial={archiveFromRow(row)}
          current={row}
          submitLabel="Save"
          pending={updateRow.isPending}
          error={updateRow.error}
          onCancel={() => setEditing(false)}
          onSubmit={values => updateRow.mutate({ id, data: toArchiveUpdateInput(values) })}
        />
      ) : (
        <dl className="grid gap-3">
        <FieldRow label="Id">{text(row.id) || "—"}</FieldRow>
        <FieldRow label="Title">{text(row.title) || "—"}</FieldRow>
        <FieldRow label="Content">
          <p className="whitespace-pre-wrap">{text(row.content) || "—"}</p>
        </FieldRow>
        <FieldRow label="Published">{row.published == null ? "—" : <Badge variant={row.published ? "default" : "outline"}>{yesNo(row.published)}</Badge>}</FieldRow>
        <FieldRow label="Author">{(row.author ? text(row.author.name) : text(row.author_id)) || "—"}</FieldRow>
        <FieldRow label="Posted At">{formatDateTime(row.posted_at) || "—"}</FieldRow>
        <FieldRow label="Tags">
          <span className="flex flex-wrap gap-1">
            {(row.tags ?? []).map(item => (
              <Badge key={text(item)} variant="secondary">
                {text(item)}
              </Badge>
            ))}
          </span>
        </FieldRow>
        <FieldRow label="Cover">
          <FilePreview file={row.cover} />
        </FieldRow>
        <FieldRow label="Publish At">{formatDateTime(row.publish_at) || "—"}</FieldRow>
        <FieldRow label="Locked">{row.locked == null ? "—" : <Badge variant={row.locked ? "default" : "outline"}>{yesNo(row.locked)}</Badge>}</FieldRow>
        <FieldRow label="Comment Count">{text(row.comment_count) || "—"}</FieldRow>
        <FieldRow label="Archived At">{formatDateTime(row.archived_at) || "—"}</FieldRow>
        <FieldRow label="Status">{row.status == null ? "—" : <Badge variant="secondary">{text(row.status)}</Badge>}</FieldRow>
        <FieldRow label="Approved At">{formatDateTime(row.approved_at) || "—"}</FieldRow>
        <FieldRow label="Retired At">{formatDateTime(row.retired_at) || "—"}</FieldRow>
        </dl>
      )}
    </Pane>
  );
}

export const ArchiveLayout = guarded(ArchiveLayoutInner);
export const ArchiveIndex = guarded(ArchiveIndexInner);
export const ArchiveNew = guarded(ArchiveNewInner);
export const ArchiveDetail = guarded(ArchiveDetailInner);
